import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    strings = []
    for _ in range(n):
        strings.append(next(iterator))

    try:
        q_count = int(next(iterator))
    except StopIteration:
        q_count = 0

    queries = []
    for _ in range(q_count):
        l = int(next(iterator))
        r = int(next(iterator))
        pattern = next(iterator)
        queries.append((l, r, pattern))

    prefix_sums = {}

    for pattern in set(p for _, _, p in queries):
        arr = [0] * (n + 1)
        current = 0
        for i, s in enumerate(strings):
            if pattern in s:
                current += 1
            arr[i + 1] = current
        prefix_sums[pattern] = arr

    output = []
    for l, r, pattern in queries:
        arr = prefix_sums.get(pattern)
        if arr is None:
            count = 0
        else:
            count = arr[r] - arr[l - 1]
        output.append(str(count))

    sys.stdout.write('\n'.join(output) + '\n')

if __name__ == "__main__":
    main()
